import { Component, computed, inject } from '@angular/core';
import { WatchlistStore, WatchItem } from '../watchlist-store';

@Component({
  selector: 'app-watchlist',
  templateUrl: './watchlist.html',
  styleUrl: './watchlist.scss',
})
export class Watchlist {
  store = inject(WatchlistStore)
  // Unwatched movies are shown first, watched ones after; within each group the
  // order in which the movies were added is kept.
  movies = computed(() => {
    const items = this.store.items();
    return items.some(m => m.watched)
      ? [...items.filter(m => !m.watched), ...items.filter(m => m.watched)]
      : items;
  })

  watchedCount = computed(() => this.movies().filter(m => m.watched).length);

  toggleWatched(id: number) {
    this.store.toggleWatched(id);
  }

  remove(id: number) {
    this.store.remove(id);
  }
}

import { TestBed, type ComponentFixture } from '@angular/core/testing';
import { Watchlist } from './watchlist';
import { WatchlistStore } from '../watchlist-store';

describe('Watchlist', () => {
  let component: Watchlist;
  let fixture: ComponentFixture<Watchlist>;
  let store: WatchlistStore;
  let el: HTMLElement;

  const items = () => Array.from(el.querySelectorAll('li'));
  const checkbox = () => el.querySelector<HTMLInputElement>('input[type="checkbox"]')!;
  const title = (i: number) => el.querySelectorAll('.title-link')[i]?.textContent ?? '';

  const addMovie = (id: number, title: string, watched = false) => {
    store.add({ id, title, release_date: '2024-01-01', poster_path: null, overview: '', watched });
  };

  beforeEach(() => {
    TestBed.configureTestingModule({ imports: [Watchlist] });
    fixture = TestBed.createComponent(Watchlist);
    component = fixture.componentInstance;
    store = TestBed.inject(WatchlistStore);
    el = fixture.nativeElement;
    addMovie(1, 'Movie 1');
    addMovie(2, 'Movie 2');
    fixture.detectChanges();
  });

  it('renders a movie for each watchlist item', () => {
    expect(items().length).toBe(2);
    expect(title(0)).toContain('Movie 1');
    expect(title(1)).toContain('Movie 2');
  });

  it('shows unwatched movies before watched ones', () => {
    addMovie(3, 'Movie 3', true);
    fixture.detectChanges();
    expect(title(0)).toContain('Movie 2');
    expect(title(1)).toContain('Movie 1');
    expect(title(2)).toContain('Movie 3');
  });

  it('toggles watched when the checkbox is clicked', () => {
    const box = checkbox();
    box.click();
    fixture.detectChanges();
    expect(box.checked).toBe(true);
    expect(component.watchedCount()).toBe(1);
  });

  it('toggles watched when blank space on the row is clicked', () => {
    const box = checkbox();
    items()[0].click();
    fixture.detectChanges();
    expect(box.checked).toBe(true);
  });

  it('removes the movie when the remove button is clicked', () => {
    (items()[0].querySelector('button') as HTMLButtonElement).click();
    fixture.detectChanges();
    expect(items().length).toBe(1);
    expect(title(0)).toContain('Movie 2');
  });

  it('has no axe accessibility violations', async () => {
    // axe analysis can be slow in a constrained sandbox; give it room.
    await expectNoA11yViolations(el);
  }, 20000);
});
